"""Warehouse fulfilment: packing slips for placed orders.

Reads orders, customers and catalogue names; never changes state.
"""

from __future__ import annotations

from dataclasses import dataclass

from orders.application.errors import Conflict, OrderNotFound, ProductNotFound
from orders.infrastructure.catalog import InMemoryProductCatalog
from orders.infrastructure.customers import InMemoryCustomerRepository
from orders.infrastructure.repository import InMemoryOrderRepository
from orders.infrastructure.stock import InMemoryStockRepository


LOW_STOCK_LINE = 5


@dataclass(frozen=True)
class FulfilmentSummary:
    open_orders: int
    units_to_pick: int
    low_stock_products: int


@dataclass(frozen=True)
class LowStockProduct:
    sku: str
    name: str
    on_hand: int


@dataclass(frozen=True)
class PackingLine:
    sku: str
    name: str | None
    quantity: int


@dataclass(frozen=True)
class PackingSlip:
    order_id: str
    customer_name: str | None
    lines: tuple[PackingLine, ...]


class FulfilmentService:
    def __init__(self, orders: InMemoryOrderRepository, customers: InMemoryCustomerRepository,
                 catalog: InMemoryProductCatalog, stock: InMemoryStockRepository) -> None:
        self._orders = orders
        self._customers = customers
        self._catalog = catalog
        self._stock = stock

    def summary(self) -> FulfilmentSummary:
        """Open (not cancelled) orders, units across them, and active products under the low-stock line."""
        open_orders = [o for o in self._orders.list_all() if o.status != "cancelled"]
        return FulfilmentSummary(
            open_orders=len(open_orders),
            units_to_pick=sum(item.quantity for o in open_orders for item in o.items),
            low_stock_products=len(self.low_stock(LOW_STOCK_LINE)),
        )

    def restock(self, sku: str, quantity: int) -> int:
        """Add ``quantity`` units to a product's stock; returns the new on-hand level."""
        if self._catalog.get(sku) is None:
            raise ProductNotFound(sku)
        new_level = self._stock.get(sku) + quantity
        self._stock.set(sku, new_level)
        return new_level

    def low_stock(self, threshold: int) -> list[LowStockProduct]:
        """Active products with stock strictly below ``threshold``, lowest stock then SKU first."""
        found = [LowStockProduct(p.sku, p.name, self._stock.get(p.sku))
                 for p in self._catalog.list_all() if p.active]
        return sorted((p for p in found if p.on_hand < threshold), key=lambda p: (p.on_hand, p.sku))

    def packing_slip(self, order_id: str) -> PackingSlip:
        """Packing slip for an order. Raises OrderNotFound, or Conflict if cancelled."""
        order = self._orders.get(order_id)
        if order is None:
            raise OrderNotFound(order_id)
        if order.status == "cancelled":
            raise Conflict(f"order {order_id} is cancelled")
        customer = self._customers.get(order.customer_id)
        lines = []
        for item in order.items:
            product = self._catalog.get(item.sku)
            lines.append(PackingLine(item.sku, product.name if product is not None else None,
                                     item.quantity))
        return PackingSlip(order.order_id, customer.name if customer is not None else None,
                           tuple(lines))
